#include <bits/stdc++.h>
using namespace std;

long long digit_pattern[20];
int min_step_count;

long long get_most_significant_digit(long long number, int &length) {
    length = 0;
    while (number >= 10) {
        number /= 10;
        length++;
    }
    return number;
}

void search_min_moves(long long current_value, int steps) {
    if (steps >= min_step_count) return;
    if (current_value == 0) {
        min_step_count = steps;
        return;
    }
    int len;
    int first_digit = get_most_significant_digit(current_value, len);
    search_min_moves(abs(current_value - digit_pattern[len] * first_digit), steps + first_digit * (len + 1));
    if (first_digit - 1 > 0)
        search_min_moves(abs(current_value - digit_pattern[len] * (first_digit - 1)), steps + (first_digit - 1) * (len + 1));
    if (first_digit > 1)
        search_min_moves(abs(digit_pattern[len + 1] - current_value), steps + (len + 2));
}

int main() {
    long long n;
    scanf("%lld", &n);
    digit_pattern[0] = 1;
    for (int i = 1; i <= 18; i++) {
        digit_pattern[i] = digit_pattern[i - 1] * 10 + 1;
    }
    min_step_count = 1e9;
    search_min_moves(n, 0);
    printf("%d\n", min_step_count);
    return 0;
}
